// GENERATED by the Video Studio server: lists every src/studio/<id>/index.tsx. Do not edit by hand.
// A project with an audio.json gets its soundtrack (voiceover + music, edited in the Audio tab) added here.
import React from 'react';
import {Composition, Folder} from 'remotion';
import type {StudioComp} from './types';
import {withStudioAudio, type AudioConfig} from './StudioAudio';
import {COMPOSITIONS as P0} from './intro-waycrm-1m-style-2';
import A0 from './intro-waycrm-1m-style-2/audio.json';
import {COMPOSITIONS as P1} from './lead-center-loop';
import {COMPOSITIONS as P2} from './tutorial-animated-screens-2';
import {COMPOSITIONS as P3} from './untitled-video';
import A3 from './untitled-video/audio.json';

const withAudio = (id: string, comps: StudioComp[], audio: AudioConfig): StudioComp[] =>
  comps.map((c) => (c.id === `Studio-${id}` ? {...c, component: withStudioAudio(c.component, audio)} : c));

const PROJECTS: [string, StudioComp[]][] = [
  ['intro-waycrm-1m-style-2', withAudio('intro-waycrm-1m-style-2', P0, A0 as AudioConfig)],
  ['lead-center-loop', P1],
  ['tutorial-animated-screens-2', P2],
  ['untitled-video', withAudio('untitled-video', P3, A3 as AudioConfig)],
];

export const StudioCompositions: React.FC = () => (
  <>
    {PROJECTS.map(([id, comps]) => (
      <Folder key={id} name={`studio-${id}`}>
        {comps.map((c) => <Composition key={c.id} {...c} />)}
      </Folder>
    ))}
  </>
);
